<?php
require_once __DIR__.'/bootstrap.php';

require QA_ROOT.'/config/database.php';require QA_ROOT.'/classes/system/StaffActivity.php';$db=(new Database)->getConnection();$checks=[];
function check($name,$ok){global $checks;if(!$ok)throw new RuntimeException($name);$checks[]=$name;}
$db->exec('CREATE TEMPORARY TABLE users(id INT PRIMARY KEY,first_name VARCHAR(80),last_name VARCHAR(80),role VARCHAR(30),is_active TINYINT,archived TINYINT NULL)');
$db->exec('CREATE TEMPORARY TABLE system_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,log_type VARCHAR(30),message TEXT,ip_address VARCHAR(60),user_agent TEXT,additional_data TEXT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP)');
$db->exec("INSERT INTO users VALUES(1,'Test','Counselor','admin',1,0),(2,'Test','Advocate','guidance_advocate',1,0),(3,'Test','Student','student',1,0),(4,'Test','Superadmin','super_admin',1,0),(5,'Disabled','Staff','admin',0,0)");
$_SERVER['REMOTE_ADDR']='::1';$_SERVER['HTTP_USER_AGENT']='Test agent';$audit=new StaffActivity($db);
foreach(StaffActivity::ACTIONS as $action=>$message){check('Whitelisted action recorded: '.$action,$audit->record(2,'manage_counseling',$action));}
check('Counselor activity recorded',$audit->record(1,'schedules','create_schedule'));check('Page visit is not recorded',!$audit->record(2,'survey_results','open_page',true));
check('Superadmin audit retained privately',$audit->record(4,'schedules','create_schedule'));
check('Student cannot generate staff activity',!$audit->record(3,'schedules','create_schedule'));check('Disabled account denied',!$audit->record(5,'schedules','create_schedule'));check('Unknown module denied',!$audit->record(1,'INJECTED_PRIVATE_CONTENT','create_schedule'));check('Unknown action denied',!$audit->record(1,'schedules','PRIVATE_PASSWORD_SENTINEL'));
$logger=new SystemLogger($db);$logger->login(2);$logger->logout(1);$logger->adminAction('Prepared school report export',2,['report'=>'ses','format'=>'csv']);$logger->info('Updated own profile details',2);
$logger->adminAction('PRIVATE_STUDENT_NOTE_SENTINEL',2);$logger->info('UNRELATED_STUDENT_SENTINEL',3);$db->exec("INSERT INTO system_logs(user_id,log_type,message,additional_data) VALUES(1,'warning','LEGACY_UNSAFE_SENTINEL','not json')");
$db->prepare('INSERT INTO system_logs(user_id,log_type,message,additional_data) VALUES(?,?,?,?)')->execute([2,'info','Opened schedules',json_encode(['staff_activity'=>1,'module'=>'schedules','action'=>'open_page','actor_role'=>'guidance_advocate'])]);
$history=$audit->history([],'admin');check('Only 10 rows per page',count($history['rows'])===10);check('Only meaningful counselor and advocate events counted',$history['total']===count(StaffActivity::ACTIONS)+3);check('Pagination has multiple pages',$history['pages']>1);
$all=[];for($p=1;$p<=$history['pages'];$p++)$all=array_merge($all,$audit->history(['activity_page'=>$p],'super_admin')['rows']);check('Pagination yields all rows without duplicates',count(array_unique(array_column($all,'id')))===$history['total']);check('Private legacy messages excluded',strpos(json_encode($all),'SENTINEL')===false);
$adv=$audit->history(['staff_role'=>'guidance_advocate'],'admin');check('Advocate role filter works',count(array_filter($adv['rows'],fn($r)=>$r['actor_role']!=='guidance_advocate'))===0);
$one=$audit->history(['staff_user'=>'1'],'admin');check('Staff-member filter works',$one['total']===1);$action=$audit->history(['activity_kind'=>'access'],'admin');check('Record access filter works',$action['total']===5);$module=$audit->history(['activity_module'=>'schedules'],'admin');check('Module filter excludes old page visits',$module['total']===1);
check('Superadmin entries hidden even with direct ID filter',$audit->history(['staff_user'=>'4'],'admin')['total']===0);check('Superadmin viewer sees the same staff-only history',$audit->history(['staff_user'=>'4'],'super_admin')['total']===0);check('Superadmin absent from staff chooser',!in_array(4,array_column($history['people'],'id')));check('Previous page visits excluded',!in_array('Opened schedules',array_column($all,'summary')));check('Sign-ins and sign-outs excluded',count(array_filter($all,fn($r)=>in_array($r['activity_kind'],['login','logout'],true)))===0);check('Print preparation filter works',$audit->history(['activity_kind'=>'print'],'admin')['total']===3);
$date=$audit->history(['activity_from'=>'2000-01-01','activity_to'=>'2000-01-02'],'admin');check('Date range and empty state work',$date['total']===0);check('Out-of-range page clamps',$audit->history(['activity_page'=>9999],'admin')['page']===$history['pages']);
try{$audit->history([],'guidance_advocate');check('Advocate cannot review staff history',false);}catch(RuntimeException $e){check('Advocate cannot review staff history',true);}
try{StaffActivity::filters(['activity_from'=>'2026-02-30']);check('Invalid date rejected',false);}catch(InvalidArgumentException $e){check('Invalid date rejected',true);}
try{StaffActivity::filters(['activity_from'=>'2026-12-01','activity_to'=>'2026-01-01']);check('Reversed dates rejected',false);}catch(InvalidArgumentException $e){check('Reversed dates rejected',true);}
$db->exec("UPDATE users SET role='student' WHERE id=2");check('Role snapshot survives role change',$audit->history(['staff_role'=>'guidance_advocate'],'admin')['total']===$adv['total']);
$raw=implode('\n',$db->query('SELECT additional_data FROM system_logs WHERE JSON_VALID(additional_data)')->fetchAll(PDO::FETCH_COLUMN));check('Metadata excludes submitted content',strpos($raw,'SENTINEL')===false&&strpos($raw,'password')===false);
check('Action resolution ignores private form contents',StaffActivity::action('manage_counseling',['start_session'=>1,'remarks'=>'PRIVATE_SENTINEL'])==='start_session');check('Unknown POST cannot generate event',StaffActivity::action('schedules',['unrelated'=>1])===null);
file_put_contents(QA_RESULTS.'/Staff-Activity-Unit-Checks.json',json_encode($checks,JSON_PRETTY_PRINT));echo count($checks)." safe audit, role, filter and pagination checks passed using temporary tables.\n";
